// Ephemeral LOCAL Supabase sessions, generated by the Auth/MFA integration test.
// Never use this harness as a public application or upload its session-fixtures.json.
import { createClient } from '@supabase/supabase-js';
import fixtures from './session-fixtures.json';
const options = { auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false } };
if (new URL(fixtures.url).hostname !== '127.0.0.1') throw Error('Only local Supabase is allowed.');
export let supabase = createClient(fixtures.url, fixtures.key, options);
export async function selectTestActor(actor: keyof typeof fixtures.sessions) {
  supabase.auth.stopAutoRefresh();
  supabase = createClient(fixtures.url, fixtures.key, options);
  const { error } = await supabase.auth.setSession(fixtures.sessions[actor]);
  if (error) throw error;
}
export const institutions = { a: fixtures.iesA, b: fixtures.iesB };
